package main

import (
	"fmt"
	"log"
	"net/http"
	_ "net/http/pprof"
	"runtime"
)

func main() {
	go func() {
		log.Println(http.ListenAndServe(":6060", nil))
	}()

	ff()

	select {}
}

func ff() {
	var ms1, ms2 runtime.MemStats

	// 记录初始内存状态
	runtime.ReadMemStats(&ms1)

	// 创建待测字符串
	s := ``
	fmt.Println(s)

	// 记录操作后内存状态
	runtime.ReadMemStats(&ms2)

	// 计算差值
	allocated := ms2.Alloc - ms1.Alloc
	fmt.Printf("内存占用：%d bytes\n", allocated/1024/1024) // 包含字符串及其底层数组[1,2,4](@ref)
}
